import AppKit
import CryptoKit
import SQLite3
import SwiftUI

struct ClipContent: Codable {
  var parts: [[String: Data]]
  static let safeTypes: [NSPasteboard.PasteboardType] = [
    .fileURL, .URL, .string, .rtf, .rtfd, .html, .png, .tiff, .pdf,
  ]
  static let excluded = Set([
    "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword", "com.typeit4me.clipping",
    "de.petermaurer.TransientPasteboardType", "Pasteboard generator type", "net.antelle.keeweb",
  ])
  static func read(_ board: NSPasteboard, ignored: Set<String> = []) -> Self? {
    let change = board.changeCount
    guard let items = board.pasteboardItems, !items.isEmpty else { return nil }
    let markers = excluded.union(ignored)
    guard !items.contains(where: { !$0.types.allSatisfy { !markers.contains($0.rawValue) } }) else {
      return nil
    }
    var total = 0
    var parts = [[String: Data]]()
    for item in items {
      var values = [String: Data]()
      for type in safeTypes where item.types.contains(type) {
        if type == .tiff, values[NSPasteboard.PasteboardType.png.rawValue] != nil { continue }
        guard let data = item.data(forType: type), !data.isEmpty else { continue }
        total += data.count
        guard total <= 32 * 1024 * 1024 else { return nil }
        values[type.rawValue] = data
      }
      guard !values.isEmpty else { return nil }
      parts.append(values)
    }
    return change == board.changeCount ? Self(parts: parts) : nil
  }
  func data(_ type: NSPasteboard.PasteboardType) -> Data? { parts.first?[type.rawValue] }
  var imageData: Data? { data(.png) ?? data(.tiff) }
  var kind: String {
    if data(.fileURL) != nil { return "文件" }
    if imageData != nil { return "图片" }
    if data(.pdf) != nil { return "PDF" }
    if data(.rtf) != nil || data(.rtfd) != nil || data(.html) != nil { return "富文本" }
    return "文本"
  }
  var plain: String? {
    parts.compactMap { part -> String? in
      for t in [NSPasteboard.PasteboardType.string, .fileURL, .URL] {
        if let d = part[t.rawValue], let text = String(data: d, encoding: .utf8) { return text }
      }
      for (t, format) in [
        (NSPasteboard.PasteboardType.rtf, NSAttributedString.DocumentType.rtf), (.rtfd, .rtfd),
      ] {
        if let d = part[t.rawValue] {
          if let text = try? NSAttributedString(
            data: d, options: [.documentType: format], documentAttributes: nil
          ).string {
            return text
          }
        }
      }
      if let html = part[NSPasteboard.PasteboardType.html.rawValue],
        let document = try? XMLDocument(
          data: html, options: [.documentTidyHTML, .nodeLoadExternalEntitiesNever])
      {
        for node in (try? document.nodes(forXPath: "//script | //style | //head")) ?? [] {
          node.detach()
        }
        for element in (try? document.nodes(forXPath: "//br | //p | //div | //li")) ?? [] {
          if element.stringValue?.hasSuffix("\n") != true,
            let newline = XMLNode.text(withStringValue: "\n") as? XMLNode
          {
            (element as? XMLElement)?.addChild(newline)
          }
        }
        return document.rootElement()?.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines)
      }
      return nil
    }.joined(separator: "\n").nonempty
  }
  var label: String {
    if kind == "文件" {
      return parts.compactMap {
        $0[NSPasteboard.PasteboardType.fileURL.rawValue].flatMap {
          String(data: $0, encoding: .utf8)
        }.flatMap { URL(string: $0)?.path }
      }.joined(separator: "\n")
    }
    return String((plain ?? kind).prefix(32768))
  }
  var fingerprint: String {
    var hash = SHA256()
    func length(_ n: Int) {
      withUnsafeBytes(of: UInt64(n).bigEndian) { hash.update(bufferPointer: $0) }
    }
    for p in parts {
      length(p.count)
      for k in p.keys.sorted() {
        let key = Data(k.utf8)
        let value = p[k]!
        length(key.count)
        hash.update(data: key)
        length(value.count)
        hash.update(data: value)
      }
    }
    return hash.finalize().map { String(format: "%02x", $0) }.joined()
  }
  func write(_ board: NSPasteboard, plainOnly: Bool) -> Bool {
    if plainOnly {
      guard let text = plain else { return false }
      board.clearContents()
      return board.setString(text, forType: .string)
    }
    let objects = parts.map { values in
      let item = NSPasteboardItem()
      for (type, data) in values { item.setData(data, forType: .init(type)) }
      return item
    }
    guard !objects.isEmpty else { return false }
    board.clearContents()
    return board.writeObjects(objects)
  }
}
extension String { fileprivate var nonempty: String? { isEmpty ? nil : self } }
struct ClipEntry: Identifiable, Equatable {
  let id: String, label: String, kind: String, app: String, pin: String?
  let date: Date
}
private let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
final class ClipDatabase {
  private var db: OpaquePointer?
  init(folder: URL) throws {
    try FileManager.default.createDirectory(
      at: folder, withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    let file = folder.appendingPathComponent("History.sqlite")
    guard sqlite3_open(file.path, &db) == SQLITE_OK else {
      let e = error
      sqlite3_close(db)
      throw e
    }
    _ = chmod(file.path, 0o600)
    try exec("PRAGMA secure_delete=ON")
    try exec(
      "CREATE TABLE IF NOT EXISTS history(id TEXT PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL,app TEXT NOT NULL,used REAL NOT NULL,pin TEXT,payload BLOB NOT NULL)"
    )
  }
  deinit { sqlite3_close(db) }
  private var error: NSError {
    NSError(
      domain: "Glint.Clipboard", code: 1,
      userInfo: [
        NSLocalizedDescriptionKey: db.map { String(cString: sqlite3_errmsg($0)) } ?? L("无法打开剪贴板记录")
      ])
  }
  private func exec(_ sql: String) throws {
    guard sqlite3_exec(db, sql, nil, nil, nil) == SQLITE_OK else { throw error }
  }
  private func statement<T>(_ sql: String, _ body: (OpaquePointer) throws -> T) throws -> T {
    var st: OpaquePointer?
    guard sqlite3_prepare_v2(db, sql, -1, &st, nil) == SQLITE_OK, let st else { throw error }
    defer { sqlite3_finalize(st) }
    return try body(st)
  }
  private func bind(_ s: String, _ index: Int32, _ st: OpaquePointer) {
    sqlite3_bind_text(st, index, s, -1, transient)
  }
  private func done(_ st: OpaquePointer) throws {
    guard sqlite3_step(st) == SQLITE_DONE else { throw error }
  }
  func add(_ c: ClipContent, app: String, limit: Int, date: Date = Date()) throws {
    let encoder = PropertyListEncoder()
    encoder.outputFormat = .binary
    let blob = try encoder.encode(c)
    try exec("BEGIN IMMEDIATE")
    do {
      try statement(
        "INSERT INTO history(id,title,kind,app,used,payload) VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET used=excluded.used, app=excluded.app"
      ) { st in
        bind(c.fingerprint, 1, st)
        bind(c.label, 2, st)
        bind(c.kind, 3, st)
        bind(app, 4, st)
        sqlite3_bind_double(st, 5, date.timeIntervalSince1970)
        _ = blob.withUnsafeBytes {
          sqlite3_bind_blob(st, 6, $0.baseAddress, Int32($0.count), transient)
        }
        try done(st)
      }
      try trim(limit)
      try exec("COMMIT")
    } catch {
      try? exec("ROLLBACK")
      throw error
    }
  }
  func trim(_ limit: Int) throws {
    // Keep pinned clips independently of the history count and the 128 MiB unpinned budget.
    try statement(
      "DELETE FROM history WHERE id IN (SELECT id FROM (SELECT id,ROW_NUMBER() OVER (ORDER BY used DESC,id) AS n,SUM(length(payload)) OVER (ORDER BY used DESC,id) AS b FROM history WHERE pin IS NULL) WHERE n>? OR b>134217728)"
    ) { st in
      sqlite3_bind_int(st, 1, Int32(max(1, min(limit, 1000))))
      try done(st)
    }
  }
  func list() throws -> [ClipEntry] {
    try statement(
      "SELECT id,title,kind,app,used,pin FROM history ORDER BY pin IS NULL,used DESC,id"
    ) { st in
      var rows = [ClipEntry]()
      while true {
        let code = sqlite3_step(st)
        if code == SQLITE_DONE { return rows }
        guard code == SQLITE_ROW else { throw error }
        func text(_ i: Int32) -> String { String(cString: sqlite3_column_text(st, i)) }
        rows.append(
          ClipEntry(
            id: text(0), label: text(1), kind: text(2), app: text(3),
            pin: sqlite3_column_type(st, 5) == SQLITE_NULL ? nil : text(5),
            date: Date(timeIntervalSince1970: sqlite3_column_double(st, 4))))
      }
    }
  }
  func content(_ id: String) throws -> ClipContent? {
    try statement("SELECT payload FROM history WHERE id=?") { st in
      bind(id, 1, st)
      guard sqlite3_step(st) == SQLITE_ROW, let bytes = sqlite3_column_blob(st, 0) else {
        return nil
      }
      return try PropertyListDecoder().decode(
        ClipContent.self, from: Data(bytes: bytes, count: Int(sqlite3_column_bytes(st, 0))))
    }
  }
  func pin(_ e: ClipEntry) throws {
    let used = Set(try list().compactMap(\.pin))
    let key = "bdefghijklmnoprstuy".map(String.init).first { !used.contains($0) } ?? ""
    try statement("UPDATE history SET pin=? WHERE id=?") { st in
      if e.pin == nil { bind(key, 1, st) } else { sqlite3_bind_null(st, 1) }
      bind(e.id, 2, st)
      try done(st)
    }
  }
  func touch(_ id: String) throws {
    try statement("UPDATE history SET used=? WHERE id=?") { st in
      sqlite3_bind_double(st, 1, Date().timeIntervalSince1970)
      bind(id, 2, st)
      try done(st)
    }
  }
  func remove(_ id: String) throws {
    try statement("DELETE FROM history WHERE id=?") { st in
      bind(id, 1, st)
      try done(st)
    }
  }
  func clear(all: Bool) throws {
    try exec(all ? "DELETE FROM history" : "DELETE FROM history WHERE pin IS NULL")
  }
}

final class ClipboardHistory: ObservableObject {
  let defaults: UserDefaults
  @Published private(set) var entries = [ClipEntry]()
  @Published var notice: String?
  @Published var showSettings = false
  @Published var clearRequest: Bool?
  @Published var interval: Double {
    didSet {
      defaults.set(interval, forKey: "clip.interval")
      updateTimer()
    }
  }
  @Published var skipOnce = false
  @Published var paused: Bool {
    didSet {
      defaults.set(paused, forKey: "clip.paused")
      last = board.changeCount
      updateTimer()
    }
  }
  @Published var limit: Int {
    didSet {
      defaults.set(limit, forKey: "clip.limit")
      let n = limit
      modify { try $0.trim(n) }
    }
  }
  @Published var ignoreApps: String {
    didSet { defaults.set(ignoreApps, forKey: "clip.ignoreApps") }
  }
  @Published var ignoreTypes: String {
    didSet { defaults.set(ignoreTypes, forKey: "clip.ignoreTypes") }
  }
  @Published var autoPaste: Bool { didSet { defaults.set(autoPaste, forKey: "clip.autoPaste") } }
  let board: NSPasteboard
  private var last: Int
  private var timer: Timer?
  private var started = false
  private let dbQueue = DispatchQueue(label: "glint.clipboard.database", qos: .utility)
  private let folder: URL
  private var database: ClipDatabase?
  init(
    folder: URL = perchSupportFolder().appendingPathComponent("Clipboard"),
    board: NSPasteboard = .general, defaults: UserDefaults = .standard
  ) {
    self.folder = folder
    self.board = board
    self.defaults = defaults
    last = board.changeCount
    let savedInterval = defaults.double(forKey: "clip.interval")
    interval = [0.1, 0.25, 0.5, 1.0].contains(savedInterval) ? savedInterval : 0.5
    paused = defaults.bool(forKey: "clip.paused")
    limit = defaults.object(forKey: "clip.limit") as? Int ?? 200
    ignoreApps = defaults.string(forKey: "clip.ignoreApps") ?? ""
    ignoreTypes = defaults.string(forKey: "clip.ignoreTypes") ?? ""
    autoPaste = defaults.bool(forKey: "clip.autoPaste")
  }
  private func db() throws -> ClipDatabase {
    if let database { return database }
    let value = try ClipDatabase(folder: folder)
    database = value
    return value
  }
  func start() {
    guard !started else { return }
    started = true
    modify { _ in }
    updateTimer()
  }
  private func updateTimer() {
    timer?.invalidate()
    timer = nil
    guard started && !paused else { return }
    let t = Timer(timeInterval: interval, repeats: true) { [weak self] _ in self?.poll() }
    t.tolerance = interval * 0.2
    RunLoop.main.add(t, forMode: .common)
    timer = t
  }
  static func names(_ text: String) -> Set<String> {
    Set(
      text.components(separatedBy: CharacterSet(charactersIn: ",;\n")).map {
        $0.trimmingCharacters(in: .whitespacesAndNewlines)
      }.filter { !$0.isEmpty })
  }
  func poll() {
    let n = board.changeCount
    guard !paused, n != last else { return }
    last = n
    if skipOnce {
      skipOnce = false
      return
    }
    let source = NSWorkspace.shared.frontmostApplication
    let app = source?.bundleIdentifier ?? ""
    guard !Self.names(ignoreApps).contains(app),
      let clip = ClipContent.read(board, ignored: Self.names(ignoreTypes)), board.changeCount == n
    else { return }
    let cap = limit
    modify { try $0.add(clip, app: app, limit: cap) }
  }
  private func modify(_ op: @escaping (ClipDatabase) throws -> Void) {
    dbQueue.async { [weak self] in
      guard let self else { return }
      do {
        let db = try self.db()
        try op(db)
        let rows = try db.list()
        DispatchQueue.main.async { self.entries = rows }
      } catch { DispatchQueue.main.async { self.notice = L("剪贴板记录 · ") + error.localizedDescription } }
    }
  }
  func pin(_ e: ClipEntry) {
    let n = limit
    modify {
      try $0.pin(e)
      try $0.trim(n)
    }
  }
  func remove(_ e: ClipEntry) { modify { try $0.remove(e.id) } }
  func clear(all: Bool) { modify { try $0.clear(all: all) } }
  func content(_ id: String) -> ClipContent? {
    do { return try dbQueue.sync { try db().content(id) } } catch {
      notice = error.localizedDescription
      return nil
    }
  }
  func copy(_ e: ClipEntry, plain: Bool) -> Bool {
    guard let value = content(e.id), value.write(board, plainOnly: plain) else {
      notice = plain ? L("这条记录没有纯文本版本") : L("无法恢复该记录")
      return false
    }
    last = board.changeCount
    modify { try $0.touch(e.id) }
    notice = L("已复制")
    return true
  }
  deinit { timer?.invalidate() }
}
